(* Tank sequence: fill, then mix, then drain, with one step bit on at a time. *)
PROGRAM TankSequence
VAR_INPUT Start AT %I0.0 : BOOL; END_VAR
VAR_OUTPUT
    FillValve AT %Q0.0 : BOOL;
    Mixer AT %Q0.1 : BOOL;
    DrainValve AT %Q0.2 : BOOL;
END_VAR
VAR
    StepFill : BOOL;
    StepMix : BOOL;
    StepDrain : BOOL;
    FillTimer : TON;
    MixTimer : TON;
    DrainTimer : TON;
END_VAR

IF Start AND NOT StepFill AND NOT StepMix AND NOT StepDrain THEN StepFill := TRUE; END_IF;
IF StepFill AND FillTimer.Q THEN StepMix := TRUE; StepFill := FALSE; END_IF;
IF StepMix AND MixTimer.Q THEN StepDrain := TRUE; StepMix := FALSE; END_IF;
IF StepDrain AND DrainTimer.Q THEN StepDrain := FALSE; END_IF;
FillTimer(IN := StepFill, PT := T#40ms);
MixTimer(IN := StepMix, PT := T#30ms);
DrainTimer(IN := StepDrain, PT := T#30ms);
FillValve := StepFill;
Mixer := StepMix;
DrainValve := StepDrain;
END_PROGRAM

